( function () {
	'use strict';
	var app = document.getElementById( 'wpfetch-app' );
	if ( ! app || ! window.wpFetchAdmin ) return;
	var cfg = window.wpFetchAdmin;
	var esc = function ( value ) { var div = document.createElement( 'div' ); div.textContent = value == null ? '' : String( value ); return div.innerHTML; };
	var request = function ( path, options ) {
		options = options || {}; options.headers = Object.assign( { 'Content-Type': 'application/json', 'X-WP-Nonce': cfg.nonce }, options.headers || {} );
		return fetch( cfg.apiRoot + path, options ).then( function ( response ) { return response.json().then( function ( body ) { if ( ! response.ok ) throw new Error( body.message || 'Request failed.' ); return { body: body, response: response }; } ); } );
	};
	var announce = function ( message ) { document.getElementById( 'wpfetch-live' ).textContent = message; var toast = document.createElement( 'div' ); toast.className = 'wpfetch-toast'; toast.setAttribute( 'role', 'status' ); toast.textContent = message; document.body.appendChild( toast ); setTimeout( function () { toast.remove(); }, 3500 ); };
	var fail = function ( error ) { app.insertAdjacentHTML( 'afterbegin', '<div class="wpfetch-alert wpfetch-alert--error" role="alert"><strong>Unable to complete the request.</strong><br>' + esc( error.message ) + '</div>' ); };
	var badge = function ( status ) { return '<span class="wpfetch-status wpfetch-status--' + esc( status ) + '">' + esc( String( status || 'unknown' ).replaceAll( '_', ' ' ) ) + '</span>'; };

	function dashboard() {
		request( '/dashboard' ).then( function ( result ) { var m = result.body.metrics, q = result.body.queue || {}; app.innerHTML = '<div class="wpfetch-grid">' + [ [ 'Total sources', m.sources ], [ 'Healthy', m.healthy ], [ 'Requires attention', m.warnings ], [ 'Imports today', m.imports_today ], [ 'Updates today', m.updates_today ], [ 'Queue pending', q.pending || 0 ], [ 'Queue failed', q.failed || 0 ], [ 'Disabled', m.disabled ] ].map( function ( metric ) { return '<div class="wpfetch-card wpfetch-metric"><span class="wpfetch-muted">' + esc( metric[0] ) + '</span><strong>' + esc( metric[1] ) + '</strong></div>'; } ).join( '' ) + '</div>' +
			'<div class="wpfetch-grid"><section class="wpfetch-card" style="grid-column:span 2"><h2>System status</h2><p><strong>SEO provider:</strong> ' + esc( result.body.seo_provider ) + '</p><p><strong>Next scheduler tick:</strong> ' + ( result.body.cron_next ? new Date( result.body.cron_next * 1000 ).toLocaleString() : 'Not scheduled' ) + '</p><p class="wpfetch-muted">WP-Cron runs when the site receives traffic. For exact schedules, run <code>wp feed-syndicator queue run</code> from real cron.</p></section><section class="wpfetch-card" style="grid-column:span 2"><h2>Get started</h2><p>Add a source, test its real response, preview normalized entries, and choose explicit publication and SEO policies.</p><a class="button button-primary" href="admin.php?page=wordpress-fetch-add">Add your first source</a> <a class="button" href="admin.php?page=wordpress-fetch-tools">Import OPML</a></section></div>'; } ).catch( fail );
	}

	function sources() {
		app.innerHTML = '<div class="wpfetch-toolbar"><input class="wpfetch-search" id="wf-search" type="search" placeholder="Search sources…" aria-label="Search sources"><select id="wf-status"><option value="">All statuses</option><option>enabled</option><option>disabled</option><option>archived</option></select></div><div id="wf-list" class="wpfetch-skeleton"></div>';
		var timer; function load() { var query = '?per_page=50&search=' + encodeURIComponent( document.getElementById( 'wf-search' ).value ) + '&status=' + encodeURIComponent( document.getElementById( 'wf-status' ).value ); request( '/sources' + query ).then( function ( result ) { var rows = result.body; var target = document.getElementById( 'wf-list' ); if ( ! rows.length ) { target.className = 'wpfetch-card wpfetch-empty'; target.innerHTML = '<span class="dashicons dashicons-rss"></span><h2>No sources found</h2><p>Connect an RSS, RDF, or Atom source, or import an OPML collection.</p><a class="button button-primary" href="admin.php?page=wordpress-fetch-add">Add source</a>'; return; } target.className = 'wpfetch-table-wrap'; target.innerHTML = '<table class="wpfetch-table"><thead><tr><th>Source</th><th>Health</th><th>Destination</th><th>Schedule</th><th>Last success</th><th>Actions</th></tr></thead><tbody>' + rows.map( function ( row ) { return '<tr><td data-label="Source"><strong>' + esc( row.name ) + '</strong><br><small>' + esc( row.feed_url ) + '</small></td><td data-label="Health">' + badge( row.health ) + '</td><td data-label="Destination"><code>' + esc( row.post_type ) + '</code> / ' + esc( row.post_status ) + '</td><td data-label="Schedule">' + esc( row.schedule ) + '</td><td data-label="Last success">' + esc( row.last_success || 'Never' ) + '</td><td data-label="Actions"><div class="wpfetch-actions"><button class="button wf-fetch" data-id="' + row.id + '">Fetch now</button><button class="button wf-test" data-id="' + row.id + '">Test</button><button class="button-link-delete wf-delete" data-id="' + row.id + '" data-name="' + esc( row.name ) + '">Delete</button></div></td></tr>'; } ).join( '' ) + '</tbody></table>'; bindSourceActions(); } ).catch( fail ); }
		document.getElementById( 'wf-search' ).addEventListener( 'input', function () { clearTimeout( timer ); timer = setTimeout( load, 300 ); } ); document.getElementById( 'wf-status' ).addEventListener( 'change', load ); load();
		function bindSourceActions() { app.querySelectorAll( '.wf-fetch,.wf-test' ).forEach( function ( button ) { button.addEventListener( 'click', function () { button.disabled = true; request( '/sources/' + button.dataset.id + '/' + ( button.classList.contains( 'wf-test' ) ? 'test' : 'fetch' ), { method: 'POST' } ).then( function ( result ) { announce( button.classList.contains( 'wf-test' ) ? 'Connection succeeded: ' + result.body.entry_count + ' entries found.' : 'Fetch queued as job ' + result.body.job_id + '.' ); } ).catch( fail ).finally( function () { button.disabled = false; } ); } ); } ); app.querySelectorAll( '.wf-delete' ).forEach( function ( button ) { button.addEventListener( 'click', function () { if ( ! window.confirm( 'Delete “' + button.dataset.name + '”? Imported posts will be preserved.' ) ) return; request( '/sources/' + button.dataset.id, { method: 'DELETE' } ).then( function () { announce( 'Source deleted; imported posts were preserved.' ); load(); } ).catch( fail ); } ); } ); }
	}

	function wizard() {
		var state = { step: 0, metadata: null, test: null, data: { name: '', website_url: '', feed_url: '', status: 'enabled', post_type: 'post', post_status: 'draft', author_id: 1, schedule: 'hourly', secret: { type: 'none' }, config: { content_mode: 'full', content_template: '{{content}}', attribution: 'Originally published by <a href="{{original_url}}">{{source_name}}</a>.', duplicate_policy: 'skip', use_source_date: true, download_media: false, seo: { policy: 'source', robots: 'noindex,follow' }, rules: { mode: 'ALL', conditions: [] }, mappings: [] } } };
		var names = [ 'Source', 'Connection', 'Destination', 'Field mapping', 'Content', 'Rules', 'Media', 'SEO', 'Schedule', 'Preview & test', 'Confirmation' ];
		request( '/metadata' ).then( function ( result ) { state.metadata = result.body; render(); } ).catch( fail );
		function value( id ) { var field = document.getElementById( id ); return field ? ( field.type === 'checkbox' ? field.checked : field.value ) : ''; }
		function collect() { state.data.name = value( 'wf-name' ) || state.data.name; state.data.website_url = value( 'wf-website' ) || state.data.website_url; state.data.feed_url = value( 'wf-feed' ) || state.data.feed_url; state.data.post_type = value( 'wf-post-type' ) || state.data.post_type; state.data.post_status = value( 'wf-post-status' ) || state.data.post_status; state.data.secret.type = value( 'wf-auth-type' ) || state.data.secret.type; state.data.secret.username = value( 'wf-auth-user' ) || state.data.secret.username; state.data.secret.password = value( 'wf-auth-pass' ) || state.data.secret.password; state.data.secret.token = value( 'wf-auth-token' ) || state.data.secret.token; state.data.secret.header_name = value( 'wf-auth-header' ) || state.data.secret.header_name; state.data.secret.header_value = value( 'wf-auth-value' ) || state.data.secret.header_value; state.data.config.content_mode = value( 'wf-content-mode' ) || state.data.config.content_mode; state.data.config.content_template = value( 'wf-template' ) || state.data.config.content_template; state.data.config.attribution = value( 'wf-attribution' ) || state.data.config.attribution; state.data.config.download_media = !! value( 'wf-download-media' ); state.data.config.seo.policy = value( 'wf-seo-policy' ) || state.data.config.seo.policy; state.data.config.seo.robots = value( 'wf-robots' ) || state.data.config.seo.robots; state.data.schedule = value( 'wf-schedule' ) || state.data.schedule; }
		function field( id, label, type, val, help, full ) { return '<div class="wpfetch-field' + ( full ? ' wpfetch-field--full' : '' ) + '"><label for="' + id + '">' + label + '</label><input id="' + id + '" type="' + type + '" value="' + esc( val ) + '"><small>' + help + '</small></div>'; }
		function render() { var d = state.data, c = d.config, html = '<ol class="wpfetch-stepper" aria-label="Setup progress">' + names.map( function ( name, i ) { return '<li class="' + ( i === state.step ? 'is-active' : '' ) + '" aria-current="' + ( i === state.step ? 'step' : 'false' ) + '">' + ( i + 1 ) + '. ' + esc( name ) + '</li>'; } ).join( '' ) + '</ol><section class="wpfetch-card"><h2>' + esc( names[state.step] ) + '</h2><div class="wpfetch-form-grid">';
			switch ( state.step ) {
				case 0: html += field( 'wf-name', 'Source name', 'text', d.name, 'A recognizable internal label.', false ) + field( 'wf-website', 'Website URL', 'url', d.website_url, 'Optional. Use discovery to find declared feeds.', false ) + field( 'wf-feed', 'Feed URL', 'url', d.feed_url, 'A public RSS, RDF, or Atom URL.', true ) + '<div><button id="wf-discover" class="button">Discover feeds automatically</button></div><div id="wf-discovered" class="wpfetch-field--full"></div>'; break;
				case 1: html += '<div class="wpfetch-field wpfetch-field--full"><p><strong>Safe connection defaults</strong></p><ul><li>15 second timeout and five redirects</li><li>Private, loopback, link-local, metadata, and non-HTTP destinations blocked</li><li>Conditional ETag / Last-Modified requests enabled</li></ul></div><div class="wpfetch-field"><label for="wf-auth-type">Authentication</label><select id="wf-auth-type"><option value="none">None</option><option value="basic">HTTP Basic</option><option value="bearer">Bearer token</option><option value="header">API key / custom header</option></select></div><div class="wpfetch-field"><label for="wf-auth-user">Username</label><input id="wf-auth-user" autocomplete="off" value="' + esc( d.secret.username || '' ) + '"><label for="wf-auth-pass">Password</label><input id="wf-auth-pass" type="password" autocomplete="new-password" value="' + esc( d.secret.password || '' ) + '"></div><div class="wpfetch-field"><label for="wf-auth-token">Bearer token</label><input id="wf-auth-token" type="password" autocomplete="new-password" value="' + esc( d.secret.token || '' ) + '"></div><div class="wpfetch-field"><label for="wf-auth-header">Custom header name</label><input id="wf-auth-header" value="' + esc( d.secret.header_name || '' ) + '"><label for="wf-auth-value">Header value</label><input id="wf-auth-value" type="password" value="' + esc( d.secret.header_value || '' ) + '"></div><div class="wpfetch-field wpfetch-field--full"><small>Secrets are encrypted with Libsodium and omitted from logs, REST responses, cloning, and exports.</small><p><button id="wf-connection-test" class="button button-primary">Test connection</button></p><div id="wf-test-result"></div></div>'; break;
				case 2: html += '<div class="wpfetch-field"><label for="wf-post-type">Destination post type</label><select id="wf-post-type">' + state.metadata.post_types.map( function ( p ) { return '<option value="' + esc( p.slug ) + '" ' + ( p.slug === d.post_type ? 'selected' : '' ) + '>' + esc( p.label ) + ' (' + esc( p.slug ) + ')</option>'; } ).join( '' ) + '</select><small>Writable types are discovered dynamically.</small></div><div class="wpfetch-field"><label for="wf-post-status">Publication status</label><select id="wf-post-status">' + state.metadata.statuses.map( function ( s ) { return '<option ' + ( s === d.post_status ? 'selected' : '' ) + '>' + s + '</option>'; } ).join( '' ) + '</select><small>Draft or pending is safest for editorial review.</small></div>'; break;
				case 3: html += '<div class="wpfetch-field wpfetch-field--full"><p>The default normalized mapping is:</p><div class="wpfetch-preview"><code>title → post_title<br>content → post_content<br>summary → post_excerpt<br>published_at → post_date<br>categories → assigned category terms<br>featured_image_url → featured image</code></div><p class="wpfetch-muted">Additional mapping rows can be supplied through the configuration REST API and extension filter <code>wpfetch_mapped_post</code>.</p></div>'; break;
				case 4: html += '<div class="wpfetch-field"><label for="wf-content-mode">Content mode</label><select id="wf-content-mode"><option value="full">Full feed content</option><option value="summary">Summary / excerpt</option><option value="title_link">Title + outbound link</option><option value="template">Custom template</option></select></div><div class="wpfetch-field wpfetch-field--full"><label for="wf-template">Content template</label><textarea id="wf-template" rows="8">' + esc( c.content_template ) + '</textarea><small>Tokens: ' + esc( state.metadata.template_tokens.map( function ( t ) { return '{{' + t + '}}'; } ).join( ', ' ) ) + '</small></div>' + field( 'wf-attribution', 'Attribution template', 'text', c.attribution, 'Availability through RSS does not establish republication rights.', true ); break;
				case 5: html += '<div class="wpfetch-field wpfetch-field--full"><div class="wpfetch-alert"><strong>Simple keyword filtering</strong><p>Rules are evaluated against normalized content. This release exposes the nested rules schema through REST; omitted rules import all valid entries.</p></div><label>Include title phrase <input id="wf-keyword" type="text" placeholder="Optional phrase"></label></div>'; break;
				case 6: html += '<div class="wpfetch-field wpfetch-field--full"><label><input id="wf-download-media" type="checkbox" ' + ( c.download_media ? 'checked' : '' ) + '> Download the best feed-provided image as the featured image</label><small>Remote files are URL-checked, size-limited, MIME-verified, deduplicated, and imported through WordPress media APIs. A failed image leaves the article safely imported for retry.</small></div>'; break;
				case 7: html += '<div class="wpfetch-alert wpfetch-alert--warning wpfetch-field--full"><strong>SEO provider: ' + esc( state.metadata.seo_provider ) + '</strong><p>Canonical hints do not guarantee search-engine behavior. Full syndicated copies commonly prefer the original source.</p></div><div class="wpfetch-field"><label for="wf-seo-policy">Canonical policy</label><select id="wf-seo-policy"><option value="source">Original source</option><option value="local">Local WordPress URL</option><option value="feed">Feed-provided canonical</option></select></div><div class="wpfetch-field"><label for="wf-robots">Robots</label><select id="wf-robots"><option value="noindex,follow">noindex, follow</option><option value="index,follow">index, follow</option><option value="noindex,nofollow">noindex, nofollow</option></select></div>'; break;
				case 8: html += '<div class="wpfetch-field"><label for="wf-schedule">Import schedule</label><select id="wf-schedule">' + state.metadata.schedules.map( function ( s ) { return '<option value="' + s + '" ' + ( s === d.schedule ? 'selected' : '' ) + '>' + s.replace( 'wpfetch_', 'Every ' ).replace( 'min', ' minutes' ) + '</option>'; } ).join( '' ) + '</select><small>WP-Cron is traffic-driven and may run late. Use WP-CLI from real cron for exact execution.</small></div>'; break;
				case 9: html += '<div class="wpfetch-field wpfetch-field--full"><button id="wf-preview" class="button button-primary">Fetch real preview</button><div id="wf-preview-result">' + previewHtml() + '</div></div>'; break;
				case 10: html += '<div class="wpfetch-field wpfetch-field--full"><h3>Ready to enable</h3><dl><dt>Source</dt><dd>' + esc( d.name ) + ' — ' + esc( d.feed_url ) + '</dd><dt>Destination</dt><dd>' + esc( d.post_type ) + ' / ' + esc( d.post_status ) + '</dd><dt>Schedule</dt><dd>' + esc( d.schedule ) + '</dd><dt>Duplicates</dt><dd>Skip existing imported content</dd><dt>Canonical</dt><dd>' + esc( c.seo.policy ) + '</dd><dt>Robots</dt><dd>' + esc( c.seo.robots ) + '</dd></dl><div class="wpfetch-alert"><strong>Licensing reminder:</strong> Confirm that your intended use is permitted by the publisher. RSS availability alone is not permission to republish.</div></div>'; break;
			}
			html += '</div><div class="wpfetch-footer-actions"><button id="wf-back" class="button" ' + ( state.step === 0 ? 'disabled' : '' ) + '>Back</button>' + ( state.step === 10 ? '<button id="wf-save" class="button button-primary">Save and enable source</button>' : '<button id="wf-next" class="button button-primary">Continue</button>' ) + '</div></section>'; app.innerHTML = html; bind();
			var mode = document.getElementById( 'wf-content-mode' ); if ( mode ) mode.value = c.content_mode; var seo = document.getElementById( 'wf-seo-policy' ); if ( seo ) seo.value = c.seo.policy; var robots = document.getElementById( 'wf-robots' ); if ( robots ) robots.value = c.seo.robots;
		}
		function previewHtml() { if ( ! state.test ) return '<p class="wpfetch-muted">No preview loaded yet.</p>'; return state.test.items.map( function ( item ) { return '<article class="wpfetch-preview"><h3>' + esc( item.title || 'Untitled' ) + '</h3><p>' + esc( item.summary || String( item.content || '' ).replace( /<[^>]*>/g, '' ).slice( 0, 220 ) ) + '</p><small>' + esc( item.published_at || 'No publication date' ) + ' · ' + esc( item.original_url ) + '</small></article>'; } ).join( '' ); }
		function bind() { var back = document.getElementById( 'wf-back' ), next = document.getElementById( 'wf-next' ); if ( back ) back.onclick = function () { collect(); state.step--; render(); }; if ( next ) next.onclick = function () { collect(); if ( state.step === 0 && ( ! state.data.name || ! state.data.feed_url ) ) { fail( new Error( 'Enter a source name and feed URL before continuing.' ) ); return; } state.step++; render(); };
			var discover = document.getElementById( 'wf-discover' ); if ( discover ) discover.onclick = function () { collect(); if ( ! state.data.website_url ) return fail( new Error( 'Enter a website URL first.' ) ); discover.disabled = true; request( '/discover', { method: 'POST', body: JSON.stringify( { url: state.data.website_url } ) } ).then( function ( result ) { var target = document.getElementById( 'wf-discovered' ); target.innerHTML = result.body.length ? result.body.map( function ( feed ) { return '<button class="button wf-feed-choice" data-url="' + esc( feed.url ) + '">' + esc( feed.title ) + ' — ' + esc( feed.type ) + '</button>'; } ).join( ' ' ) : '<div class="wpfetch-alert wpfetch-alert--warning">No declared feeds were found. You can still enter one manually.</div>'; target.querySelectorAll( '.wf-feed-choice' ).forEach( function ( button ) { button.onclick = function () { document.getElementById( 'wf-feed' ).value = button.dataset.url; state.data.feed_url = button.dataset.url; announce( 'Feed selected.' ); }; } ); } ).catch( fail ).finally( function () { discover.disabled = false; } ); };
			var test = document.getElementById( 'wf-connection-test' ); if ( test ) { var authType = document.getElementById( 'wf-auth-type' ); if ( authType ) authType.value = d.secret.type; test.onclick = function () { collect(); test.disabled = true; request( '/test', { method: 'POST', body: JSON.stringify( { url: state.data.feed_url, secret: state.data.secret } ) } ).then( function ( result ) { state.test = result.body; document.getElementById( 'wf-test-result' ).innerHTML = '<div class="wpfetch-alert"><strong>Connected in ' + esc( result.body.response_time_ms ) + ' ms.</strong><br>' + esc( result.body.detected_format.toUpperCase() ) + ' · ' + esc( result.body.entry_count ) + ' entries · ' + esc( result.body.title ) + '</div>'; announce( 'Connection test succeeded.' ); } ).catch( fail ).finally( function () { test.disabled = false; } ); }; }
			var preview = document.getElementById( 'wf-preview' ); if ( preview ) preview.onclick = function () { request( '/test', { method: 'POST', body: JSON.stringify( { url: state.data.feed_url } ) } ).then( function ( result ) { state.test = result.body; document.getElementById( 'wf-preview-result' ).innerHTML = previewHtml(); announce( 'Preview loaded without saving content.' ); } ).catch( fail ); };
			var save = document.getElementById( 'wf-save' ); if ( save ) save.onclick = function () { collect(); save.disabled = true; request( '/sources', { method: 'POST', body: JSON.stringify( state.data ) } ).then( function ( result ) { announce( 'Source saved and enabled.' ); window.location.href = 'admin.php?page=wordpress-fetch-sources&created=' + result.body.id; } ).catch( fail ).finally( function () { save.disabled = false; } ); };
		}
	}

	function activity() { request( '/logs?per_page=100' ).then( function ( result ) { app.innerHTML = result.body.length ? '<div class="wpfetch-table-wrap"><table class="wpfetch-table"><thead><tr><th>Time</th><th>Severity</th><th>Event</th><th>Source</th><th>Message</th></tr></thead><tbody>' + result.body.map( function ( row ) { return '<tr><td data-label="Time">' + esc( row.created_at ) + '</td><td data-label="Severity">' + badge( row.severity ) + '</td><td data-label="Event"><code>' + esc( row.event ) + '</code></td><td data-label="Source">' + esc( row.source_id || '—' ) + '</td><td data-label="Message">' + esc( row.message ) + '</td></tr>'; } ).join( '' ) + '</tbody></table></div>' : '<div class="wpfetch-card wpfetch-empty"><h2>No activity yet</h2><p>Connection tests, fetches, imports, and failures will appear here without credentials.</p></div>'; } ).catch( fail ); }

	function tools() { Promise.all( [ request( '/settings' ), request( '/dashboard' ) ] ).then( function ( results ) { var settings = results[0].body, dash = results[1].body; app.innerHTML = '<div class="wpfetch-grid"><section class="wpfetch-card" style="grid-column:span 2"><h2>System health</h2><p><strong>Plugin:</strong> ' + esc( cfg.seoProvider ) + '</p><p><strong>Schema:</strong> 1.0.0</p><p><strong>Queue:</strong> <code>' + esc( JSON.stringify( dash.queue ) ) + '</code></p><p><strong>Scheduler:</strong> ' + ( dash.cron_next ? new Date( dash.cron_next * 1000 ).toLocaleString() : 'Not scheduled' ) + '</p></section><section class="wpfetch-card" style="grid-column:span 2"><h2>Operational defaults</h2><div class="wpfetch-field"><label for="wf-batch">Queue batch size</label><input id="wf-batch" type="number" min="1" max="100" value="' + esc( settings.queue_batch_size ) + '"></div><div class="wpfetch-field"><label for="wf-retention">Log retention days</label><input id="wf-retention" type="number" min="1" max="365" value="' + esc( settings.log_retention_days ) + '"></div><p><button id="wf-save-settings" class="button button-primary">Save settings</button></p></section></div><section class="wpfetch-card"><h2>OPML import</h2><p>Paste OPML to inspect its hierarchy and validate feed URLs. Duplicates are collapsed before import.</p><textarea id="wf-opml" rows="9" class="large-text code"></textarea><p><button id="wf-parse-opml" class="button">Preview OPML</button></p><div id="wf-opml-result"></div></section><section class="wpfetch-card"><h2>Diagnostics</h2><p>WordPress ' + esc( window.wp && wp.version ? wp.version : 'environment' ) + ' · SEO owner: ' + esc( dash.seo_provider ) + '</p><pre class="wpfetch-code">' + esc( JSON.stringify( dash, null, 2 ) ) + '</pre></section>';
			app.insertAdjacentHTML( 'beforeend', '<section class="wpfetch-card"><h2>Configuration import / export</h2><p>Exports omit credentials. Imports are validated and previewed before changes are applied; imported sources start disabled.</p><p><button id="wf-export-config" class="button">Export JSON</button> <button id="wf-validate-config" class="button">Validate pasted JSON</button> <button id="wf-import-config" class="button button-primary">Apply validated import</button></p><textarea id="wf-config-json" rows="12" class="large-text code" aria-label="Configuration JSON"></textarea></section>' );
			document.getElementById( 'wf-export-config' ).onclick = function () { request( '/configuration/export' ).then( function ( exported ) { document.getElementById( 'wf-config-json' ).value = JSON.stringify( exported.body, null, 2 ); announce( 'Configuration exported without credentials.' ); } ).catch( fail ); };
			document.getElementById( 'wf-validate-config' ).onclick = function () { try { var data = JSON.parse( document.getElementById( 'wf-config-json' ).value ); request( '/configuration/validate', { method: 'POST', body: JSON.stringify( data ) } ).then( function ( result ) { announce( result.body.valid ? 'Configuration is valid. Review the plan before applying.' : result.body.errors.join( ' ' ) ); } ).catch( fail ); } catch ( error ) { fail( new Error( 'The pasted configuration is not valid JSON.' ) ); } };
			document.getElementById( 'wf-import-config' ).onclick = function () { if ( ! window.confirm( 'Import this configuration? New sources will be created disabled and credentials will remain omitted.' ) ) return; try { var data = JSON.parse( document.getElementById( 'wf-config-json' ).value ); data.confirm = true; request( '/configuration/import', { method: 'POST', body: JSON.stringify( data ) } ).then( function ( result ) { announce( result.body.created.sources + ' sources imported as disabled.' ); } ).catch( fail ); } catch ( error ) { fail( new Error( 'The pasted configuration is not valid JSON.' ) ); } };
			document.getElementById( 'wf-save-settings' ).onclick = function () { settings.queue_batch_size = Number( document.getElementById( 'wf-batch' ).value ); settings.log_retention_days = Number( document.getElementById( 'wf-retention' ).value ); request( '/settings', { method: 'PUT', body: JSON.stringify( settings ) } ).then( function () { announce( 'Settings saved.' ); } ).catch( fail ); };
			document.getElementById( 'wf-parse-opml' ).onclick = function () { request( '/opml/parse', { method: 'POST', body: JSON.stringify( { opml: document.getElementById( 'wf-opml' ).value } ) } ).then( function ( result ) { var target = document.getElementById( 'wf-opml-result' ); target.innerHTML = '<p><strong>' + result.body.length + ' unique feeds found.</strong></p>' + result.body.map( function ( feed, i ) { return '<label style="display:block;margin:8px"><input class="wf-opml-feed" type="checkbox" checked data-i="' + i + '" ' + ( feed.valid ? '' : 'disabled' ) + '> ' + esc( feed.group ? feed.group + ' / ' : '' ) + esc( feed.title ) + ' — ' + ( feed.valid ? 'valid' : 'blocked URL' ) + '</label>'; } ).join( '' ) + '<button id="wf-import-opml" class="button button-primary">Import selected as disabled sources</button>'; document.getElementById( 'wf-import-opml' ).onclick = function () { var selected = Array.from( document.querySelectorAll( '.wf-opml-feed:checked' ) ).map( function ( input ) { return result.body[Number( input.dataset.i )]; } ); request( '/opml/import', { method: 'POST', body: JSON.stringify( { feeds: selected, defaults: { post_type: 'post', post_status: 'draft', schedule: 'hourly', config: {} } } ) } ).then( function ( imported ) { announce( imported.body.created + ' sources imported.' ); } ).catch( fail ); }; } ).catch( fail ); };
		} ).catch( fail ); }

	if ( cfg.page === 'wordpress-fetch' ) dashboard(); else if ( cfg.page === 'wordpress-fetch-sources' ) sources(); else if ( cfg.page === 'wordpress-fetch-add' ) wizard(); else if ( cfg.page === 'wordpress-fetch-activity' ) activity(); else tools();
} )();
